            Assert.Equal("Atalaya", Lore.Expediente[0].Title);
            Assert.Equal("La Pandemia lo vació todo. Atalaya cayó en otoño; los que quedan empiezan de cero en un claro del pinar.", Lore.Expediente[0].Summary);
            Assert.Equal(new string[] { "Hace dos inviernos llegó la Pandemia. Quien se contagia muere en un día y se levanta. Cayeron las ciudades, se fue el ejército y la radio se quedó muda.", "Atalaya era una estación militar: muros de hormigón, un refugio bajo tierra y una sola carretera. Aguantó dos años. En otoño llegó una horda y fue derecha a ella, como si alguien le hubiera enseñado el camino. Salimos en el todoterreno de Teo, con la caravana enganchada detrás. El autobús se quedó en la cochera de Atalaya, y el nombre de La Lata ha pasado al todoterreno.", "Hemos parado en un claro del pinar, sobre Bielsa. Lo que se levante aquí será el Bastión. Lo dirigen dos personas, y lo importante lo deciden juntas. El año pasado, en otro refugio, una líder sola lo vendió a los Cuervos a cambio de su vida." }, Lore.Expediente[0].Paragraphs);
            Assert.Equal("Lo que entra por la puerta se apunta aquí. — N. A.", Lore.Expediente[0].Note);
            Assert.Equal("Notas de la doctora", Lore.Expediente[1].Title);
            Assert.Equal("De noche ven igual que de día. Una puerta no los para. No todos los mordiscos contagian.", Lore.Expediente[1].Summary);
            Assert.Equal(new string[] { "Notas de la Dra. Nwosu. La oscuridad no les quita nada: de noche ven igual que de día. Los que perdemos vista somos nosotros.", "Una puerta cerrada no los para: la empujan y pasan. Solo les tapa la vista. Para frenarlos sirve un paso estrecho, no una puerta.", "No todos los mordiscos contagian. El de un muerto corriente, uno de cada cuatro; el de un Acorazado, uno de cada tres. Los gases de un Hinchado, uno de cada dos." }, Lore.Expediente[1].Paragraphs);
            Assert.Null(Lore.Expediente[1].Note);
            Assert.Equal("Los Cuervos", Lore.Expediente[2].Title);
            Assert.Equal("Los Cuervos atraen hordas con sirenas contra quien no les paga. Sin sirena, la zona respira.", Lore.Expediente[2].Summary);
            Assert.Equal(new string[] { "Los Cuervos no son una banda: son muchas, con un mismo negocio. Cobran peaje en comida y en gente.", "Su arma más sucia es la sirena de un coche patrulla. Lo llevan cerca de quien no paga, la encienden y dejan que la horda haga el resto.", "Cuando se calló la sirena de los Llanos, los zombis se dispersaron en un día. Sin ruido, se pierden." }, Lore.Expediente[2].Paragraphs);
            Assert.Equal("Las sirenas primero. Siempre. — N. A.", Lore.Expediente[2].Note);
            Assert.Equal("La Marea", Lore.Expediente[3].Title);
            Assert.Equal("Una horda inmensa sube desde los Llanos con el deshielo. Desde hoy, la contamos en kilómetros.", Lore.Expediente[3].Summary);
            Assert.Equal(new string[] { "La radio vuelve a funcionar, y lo primero que hemos oído son los demás enclaves contando lo mismo: algo sube desde los Llanos de Ceniza.", "No es una horda: son todas a la vez. Miles de zombis caminando juntos hacia la sierra con el deshielo. La llaman la Marea.", "Los Nidos la alimentan. Cada Nido que quememos la frena. Desde hoy, el reloj cuenta kilómetros." }, Lore.Expediente[3].Paragraphs);
