            Assert.Equal(new string[] { "Hay gente a la que la Pandemia no mata. Se contagian, tienen fiebre y al día siguiente siguen vivos.", "Los Cuervos lo saben y los cazan: un inmune vale más que un camión de comida.", "La Dra. Nwosu dice que con la sangre de un inmune y los cuadernos del Instituto se podría hacer una vacuna." }, Lore.Expediente[4].Paragraphs);
