            Assert.Equal("Nadie lo ha tocado desde el primer invierno. Llenad las mochilas y volved a La Lata. Vendrán, y antes cuanto más ruido hagáis.", Lore.PlainMarks("Nadie lo ha tocado **desde el primer invierno**. ==Llenad las mochilas y volved a La Lata.== Vendrán, y antes cuanto más ruido hagáis."));
